// Parse RapidAPI Zillow56 response
const data = $input.item.json;

// Get user data from webhook
const webhookData = $('Keep User Details').first().json;

console.log('Raw API Data:', JSON.stringify(data, null, 2));

// Extract property details with fallbacks
let price = 'N/A';
if (data.price) {
  price = typeof data.price === 'number' 
    ? `$${data.price.toLocaleString()}` 
    : data.price;
}

// Address
let fullAddress = 'Unknown Address';
if (data.address) {
  if (typeof data.address === 'string') {
    fullAddress = data.address;
  } else {
    const street = data.address.streetAddress || '';
    const city = data.address.city || '';
    const state = data.address.state || '';
    fullAddress = `${street}, ${city}, ${state}`.trim();
  }
}

// Beds, baths, sqft
const beds = data.bedrooms || 'N/A';
const baths = data.bathrooms || 'N/A';
const sqft = data.livingArea || 'N/A';

// Description
let description = data.description || '';

// Extract images - CRITICAL SECTION
const allImages = [];

// Try multiple possible image locations in the API response
if (data.photos && Array.isArray(data.photos)) {
  console.log('Found photos array:', data.photos.length);

  data.photos.forEach((photo, i) => {
    let imageUrl = null;

    if (typeof photo === 'string') {
      imageUrl = photo;
    } else if (photo.mixedSources?.jpeg) {
      const jpegSources = photo.mixedSources.jpeg;
      // Get the largest image
      imageUrl = jpegSources[jpegSources.length - 1]?.url;
    } else if (photo.url) {
      imageUrl = photo.url;
    }

    if (imageUrl) {
      allImages.push({
        url: imageUrl,
        caption: photo.caption || ''
      });
    }
  });
}

// Also check for 'images' field
if (data.images && Array.isArray(data.images)) {
  console.log('Found images array:', data.images.length);

  data.images.forEach((img, i) => {
    const imageUrl = typeof img === 'string' ? img : img.url;
    if (imageUrl) {
      allImages.push({
        url: imageUrl,
        caption: img.caption || ''
      });
    }
  });
}

console.log('Total images found:', allImages.length);
console.log('Image URLs:', allImages.map(img => img.url));

// Smart selection: prioritize interior images
const priorityKeywords = ['kitchen', 'living', 'dining', 'bedroom', 'bath'];
const excludeKeywords = ['exterior', 'front', 'street', 'yard', 'driveway'];

const interiorImages = [];
const exteriorImages = [];

allImages.forEach(img => {
  const caption = img.caption.toLowerCase();
  const isInterior = priorityKeywords.some(k => caption.includes(k));
  const isExterior = excludeKeywords.some(k => caption.includes(k));

  if (isInterior && !isExterior) {
    interiorImages.push(img);
  } else if (isExterior) {
    exteriorImages.push(img);
  }
});

// Select 2 interior + 1 exterior (or fallback)
let selectedImages = [
  ...interiorImages.slice(0, 2),
  ...exteriorImages.slice(0, 1)
];

// Fallback: if we don't have enough, use first 3 images
if (selectedImages.length < 3) {
  selectedImages = allImages.slice(0, 3);
}

const imageUrls = selectedImages.map(img => img.url);

console.log('Selected images:', imageUrls);

// ERROR CHECK
if (imageUrls.length === 0) {
  throw new Error('No images found in API response! Check the API data structure.');
}

if (imageUrls.length < 3) {
  console.warn(`Only found ${imageUrls.length} images, expected 3. Will use what's available.`);
}

return {
  price: String(price),
  address: fullAddress,
  beds: String(beds),
  baths: String(baths),
  sqft: String(sqft),
  description: String(description).slice(0, 500),
  images: imageUrls,
  imageCount: imageUrls.length,
  name: webhookData.name,
  email: webhookData.email
};

