// Extract descriptions from Groq response
const response = $input.item.json;
const content = response.choices[0].message.content;

// Get user data from webhook
const webhookData = $('Keep User Details').first().json;

// Split into individual descriptions (remove numbering)
const descriptions = content
  .split('\n')
  .filter(line => line.trim().length > 10)
  .map(line => line.replace(/^\d+\.\s*/, '').trim())
  .slice(0, 3);

// Get property data from previous node
const propertyData = $('Parse RapidAPI Data').first().json;

// Map each image to its description
const imageData = propertyData.images.map((imageUrl, index) => ({
  imageUrl,
  description: descriptions[index] || 'Beautiful property feature with smooth camera movement',
  index,
  type: index < 2 ? 'interior' : 'exterior' // Label for tracking
}));

return imageData.map(item => ({
  ...propertyData,
  currentImage: item.imageUrl,
  currentDescription: item.description,
  imageIndex: item.index,
  imageType: item.type,
  // CRITICAL: Pass user data forward
  name: webhookData.name,
  email: webhookData.email
}));

// --- 1. Get API Response Data (Input) ---
const apiResponse = $input.item.json;

// --- 2. CRITICAL: Handle API Failure ---
if (apiResponse.code !== 200 || !apiResponse.data || !apiResponse.data.taskId) {
  throw new Error(`Kie.ai Task Creation Failed. Code: ${apiResponse.code || 'N/A'}, Msg: ${apiResponse.msg || 'No Task ID returned.'}`);
}

// --- 3. Get Data from Current Input (NOT from other nodes) ---
// Everything we need should already be in $input from the previous node
const taskId = apiResponse.data.taskId;

// Try to get data from $input first (passed through from previous nodes)
const safePrompt = $input.item.json.safePrompt || 'Video prompt not available';
const imageUrl = $input.item.json.gdrivePublicUrl || $input.item.json.imageUrl || 'Image URL not available';
const address = $input.item.json.address || 'Address not available';
const price = $input.item.json.price || 'N/A';
const beds = $input.item.json.beds || 'N/A';
const baths = $input.item.json.baths || 'N/A';
const sqft = $input.item.json.sqft || 'N/A';
const name = $input.item.json.name || 'Customer';
const email = $input.item.json.email || '';

console.log('=== STORE TASK INFO DEBUG ===');
console.log('Task ID:', taskId);
console.log('Prompt:', safePrompt);
console.log('Image URL:', imageUrl);
console.log('Input data keys:', Object.keys($input.item.json));

// --- 4. Return Combined Data ---
return {
  taskId: taskId,
  description: safePrompt,
  imageUrl: imageUrl,
  address: address,
  price: price,
  beds: beds,
  baths: baths,
  sqft: sqft,
  name: name,
  email: email
};

