const statusResponse = $input.item.json;

// Handle "recordInfo is null" - task not ready yet
if (statusResponse.code === 422 || !statusResponse.data) {
  return {
    status: 'pending',
    needsRetry: true,
    taskId: $('Store Task Info').item.json.taskId,
    ...$('Store Task Info').item.json
  };
}

// Check for failure
if (statusResponse.data.state && statusResponse.data.state.includes('fail')) {
  throw new Error(`Video failed: ${statusResponse.data.state}`);
}

// Check for success
if (statusResponse.data.state && statusResponse.data.state.includes('success')) {

  // 1. Get the original data (address, email, etc.) from the start of the loop
  const originalData = $('Store Task Info').item.json;

  // 2. Parse the result JSON string from the API response
  const resultData = JSON.parse(statusResponse.data.resultJson);

  // 3. Get the first URL from the "resultUrls" array
  const videoUrl = resultData.resultUrls[0];

  // 4. Return EVERYTHING combined
  return {
    ...originalData,     // This has address, email, imageIndex, etc.
    ...statusResponse,   // This has the API's success data
    status: 'complete',
    needsRetry: false,
    video_url: videoUrl  // This adds the new video URL!
  };
}
// Still processing
return {
  status: 'processing',
  needsRetry: true,
  ...statusResponse
};

const MAX_RETRIES = 40; // 40 retries × 45s = 30 minutes total

// Get current retry count (default to 0)
const retryCount = $json.retryCount || 0;

if (retryCount >= MAX_RETRIES) {
  throw new Error(`Video generation timeout after ${MAX_RETRIES} retries (${MAX_RETRIES * 45} seconds)`);
}

// Increment and pass through
return {
  ...$json,
  retryCount: retryCount + 1
};

// Debug the payload being sent to Kie.ai
const payload = $json['Task Payload'];

console.log('=== KIE.AI REQUEST DEBUG ===');
console.log('Full Payload:', JSON.stringify(payload, null, 2));
console.log('Image URL:', payload.input?.image_url);
console.log('Prompt:', payload.input?.prompt);
console.log('Resolution:', payload.input?.resolution);
console.log('Duration:', payload.input?.duration);

return $json;

// --- 1. Get data from the file chain (input) ---
// This has the safePrompt, gdrivePublicUrl, etc.
const fileData = $input.item.json;

// --- 2. Get this item's original data using its INDEX ---
// $itemIndex is the current item's position (0, 1, or 2)
const allItems = $('Prepare Image Data').all();
const currentItem = allItems[$itemIndex]; // Get item at index 0, 1, or 2

// If we can't find it, throw an error
if (!currentItem) {
  throw new Error(`Could not find matching item for itemIndex: ${$itemIndex}`);
}

// This is the original data for *this* item
const originalData = currentItem.json;

// --- 3. Build the Task Payload ---
const taskPayload = {
  model: "bytedance/v1-pro-fast-image-to-video",
  input: {
    prompt: fileData.safePrompt, // Use the prompt from the file chain
    image_url: fileData.gdrivePublicUrl,
    resolution: "720p",
    duration: "5"
  }
};

// --- 4. Return EVERYTHING combined ---
return {
  "Task Payload": taskPayload,
  // Add all the original property and user data back in
  ...originalData,
  // Add the new file/prompt data
  ...fileData
};

// This code handles both single items and arrays of items
let videoItems = [];

// Check if items is defined
if (typeof items === 'undefined' || !items) {
  // Single item mode - convert to array
  videoItems = [$input.item.json];
  console.log('Single item mode');
} else if (items.length === 0) {
  throw new Error('No video items received. Workflow may have failed earlier.');
} else {
  // Multiple items mode
  videoItems = items.map(item => item.json);
  console.log('Multiple items mode:', items.length);
}

console.log('=== AGGREGATE URLs DEBUG ===');
console.log('Video items:', videoItems.length);

// Organize all video clips
const videos = videoItems.map((itemData, idx) => ({
  videoUrl: itemData.video_url,
  description: itemData.description || itemData.currentDescription || 'Video clip',
  imageIndex: itemData.imageIndex !== undefined ? itemData.imageIndex : idx,
  imageType: itemData.imageType || 'unknown',
  gdriveFileId: itemData.gdriveFileId || null
})).sort((a, b) => a.imageIndex - b.imageIndex);

// Get property data from the first item
const firstItem = videoItems[0];

// Calculate costs
const costPerVideo = 0.08;
const totalCost = videos.length * costPerVideo;

return {
  success: true,
  property: {
    address: firstItem.address || 'N/A',
    price: firstItem.price || 'N/A',
    beds: firstItem.beds || 'N/A',
    baths: firstItem.baths || 'N/A',
    sqft: firstItem.sqft || 'N/A',
    name: firstItem.name || 'Customer',
    email: firstItem.email || ''
  },
  videos: videos,
  gdriveFileIds: videos.map(v => v.gdriveFileId).filter(id => id !== null),
  videoCount: videos.length,
  cost: {
    total: totalCost,
    perVideo: costPerVideo,
    breakdown: {
      interior: Math.min(2, videos.length) * costPerVideo,
      exterior: Math.max(0, videos.length - 2) * costPerVideo,
      total: totalCost
    }
  },
  apiCredits: {
    total: videos.length * 16,
    perVideo: 16
  },
  processingTime: new Date().toISOString()
};

// MODE: Run Once per Item
const item = $input.item;

// Check if a previous node failed (from "Continue on Fail")
if (item.error) {
  console.log("A previous node failed:", JSON.stringify(item.error));
  return {
    ...item.json, // Pass along any data we still have
    video_url: 'Generation Failed (API Error)'
  };
}

// Check if the video URL exists in the successful item
const result = item.json;
if (!result.video_url) {
  console.log("No video_url found in item:", JSON.stringify(result));
  return {
    ...item.json,
    video_url: 'Generation Failed (No URL Found)'
  };
}

// Success!
return {
  ...item.json,
  video_url: result.video_url
};

// This code runs ONCE after all 3 items arrive
const allItems = $items.map(item => item.json);

// Get all the common data from the first item
// (name, email, address, etc. are the same for all 3)
const firstItem = allItems[0];

// Create a new, single JSON object with all data
return {
  // Copy all the common data from the first item
  ...firstItem,

  // --- CRITICAL PART ---
  // Get the 3 video URLs from the 3 separate items
  clip1_url: allItems[0]?.video_url || 'Generation Failed',
  clip2_url: allItems[1]?.video_url || 'Generation Failed',
  clip3_url: allItems[2]?.video_url || 'Generation Failed'
};

// Organize all video clips and get GDrive IDs
const videos = items.map(item => ({
  videoUrl: item.json.videoUrl,
  description: item.json.description,
  imageIndex: item.json.imageIndex,
  imageType: item.json.imageType,
  gdriveFileId: item.json.gdriveFileId
})).sort((a, b) => a.imageIndex - b.imageIndex);

// Get property data from the first item
const firstItem = items[0].json;

// Calculate costs (5s videos at 720p = $0.08 each)
const costPerVideo = 0.08;
const totalCost = videos.length * costPerVideo;

return {
  success: true,
  property: {
    address: firstItem.address,
    price: firstItem.price,
    beds: firstItem.beds,
    baths: firstItem.baths,
    sqft: firstItem.sqft,
    name: firstItem.name,
    email: firstItem.email
  },
  videos: videos,
  gdriveFileIds: videos.map(v => v.gdriveFileId),
  videoCount: videos.length,
  cost: {
    total: totalCost,
    perVideo: costPerVideo,
    breakdown: {
      interior: 2 * costPerVideo,
      exterior: 1 * costPerVideo,
      total: totalCost
    }
  },
  apiCredits: {
    total: videos.length * 16, // 16 credits per 5s video at 720p
    perVideo: 16
  },
  processingTime: new Date().toISOString()
};
